document.querySelectorAll('.reveal').forEach(el=>new IntersectionObserver(([e],o)=>{if(e.isIntersecting){e.target.classList.add('visible');o.disconnect()}},{threshold:.1}).observe(el));
document.querySelectorAll('[data-calc]').forEach(form=>form.addEventListener('input',()=>{const amount=+(form.querySelector('[name=amount]')?.value||0);const rate=+(form.querySelector('[name=rate]')?.value||0)/1200;const years=+(form.querySelector('[name=years]')?.value||0);const months=years*12;const payment=rate&&months?amount*rate*Math.pow(1+rate,months)/(Math.pow(1+rate,months)-1):0;const out=form.querySelector('[data-result]');if(out)out.textContent=Math.round(payment).toLocaleString('ru-RU')+' ₽'}));
